// Extrair dados da mensagem da Evolution API
const body = $input.first().json.body || $input.first().json;

const data = body.data || body;
const key = data.key || {};
const message = data.message || {};

const phone = (key.remoteJid || '').replace('@s.whatsapp.net', '').replace('@c.us', '');
const fromMe = key.fromMe || false;
const isGroup = (key.remoteJid || '').includes('@g.us');
const text = (message.conversation || message.extendedTextMessage?.text || '').trim();

// Ignorar mensagens próprias e de grupos
if (fromMe || isGroup || !text) {
  return [];
}

return [{
  json: {
    phone,
    text,
    textLower: text.toLowerCase().trim()
  }
}];

// Comando não reconhecido + usuário não encontrado
const phone = $('Extrair Mensagem').item.json.phone;

return [{
  json: {
    phone,
    message: '❌ Seu número não está cadastrado no WhatsApp Fin.\n\nCadastre-se no app e vincule seu número em:\n*Configurações → Perfil → Telefone/WhatsApp*'
  }
}];

const accounts = $input.all().map(i => i.json);
const phone = $('Extrair Mensagem').item.json.phone;
const name = $('Identificar Usuário').item.json.first_name || 'Usuário';

if (accounts.length === 0) {
  return [{ json: { phone, message: `${name}, você ainda não tem contas cadastradas no app. 📱` } }];
}

let total = 0;
const lines = accounts.map(acc => {
  const balance = Number(acc.balance);
  total += balance;
  const emoji = balance >= 0 ? '🟢' : '🔴';
  return `${emoji} *${acc.name}* (${acc.type})\n   R$ ${balance.toFixed(2)}`;
});

const message = [
  `💰 *Saldo das Contas* — ${name}`,
  '',
  ...lines,
  '',
  `━━━━━━━━━━━━━━━━`,
  `📊 *Total:* R$ ${total.toFixed(2)}`,
  '',
  `_WhatsApp Fin • ${new Date().toLocaleDateString('pt-BR')}_`
].join('\n');

return [{ json: { phone, message } }];

const txs = $input.all().map(i => i.json);
const phone = $('Extrair Mensagem').item.json.phone;
const name = $('Identificar Usuário').item.json.first_name || 'Usuário';

if (txs.length === 0) {
  return [{ json: { phone, message: `${name}, nenhum gasto encontrado este mês. 🎉` } }];
}

let total = 0;
const lines = txs.map(tx => {
  const amount = Number(tx.amount);
  total += amount;
  const date = new Date(tx.date).toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit' });
  return `💸 ${date} — *${tx.description}*: R$ ${amount.toFixed(2)}`;
});

const message = [
  `📋 *Últimos Gastos* — ${name}`,
  '',
  ...lines,
  '',
  `━━━━━━━━━━━━━━━━`,
  `💰 *Total:* R$ ${total.toFixed(2)}`,
  '',
  `_WhatsApp Fin • ${new Date().toLocaleDateString('pt-BR')}_`
].join('\n');

return [{ json: { phone, message } }];

// Parser: "recebi 500 salário" ou "entrada 1200 freelance"
const text = $('Extrair Mensagem').item.json.text;
const phone = $('Extrair Mensagem').item.json.phone;
const userId = $('Identificar Usuário').item.json.id;

// Extrair valor numérico
const valueMatch = text.match(/([\d]+[.,]?[\d]*)/);
if (!valueMatch) {
  return [{ json: { phone, message: '❓ Não entendi o valor. Envie assim:\n\n*recebi 500 salário*\n*recebi 1200,50 freelance*', skip: true } }];
}

const amount = parseFloat(valueMatch[1].replace(',', '.'));

// Extrair descrição (tudo depois do valor)
const parts = text.split(valueMatch[0]);
let description = (parts[1] || 'Receita via WhatsApp').trim();
if (!description || description.length < 2) description = 'Receita via WhatsApp';

// Capitalizar
description = description.charAt(0).toUpperCase() + description.slice(1);

const id = crypto.randomUUID ? crypto.randomUUID() : `wpp-${Date.now()}`;

return [{
  json: {
    phone,
    userId,
    skip: false,
    transaction: {
      id,
      user_id: userId,
      description,
      amount,
      type: 'income',
      date: new Date().toISOString().split('T')[0],
      account_id: null,
      category_id: null
    },
    confirmMessage: `✅ *Receita registrada!*\n\n💰 *${description}*\nValor: R$ ${amount.toFixed(2)}\nData: ${new Date().toLocaleDateString('pt-BR')}\n\n_Registrado via WhatsApp Fin_`
  }
}];

// Parser: "gastei 50 almoço" ou "comprei 200 mercado"
const text = $('Extrair Mensagem').item.json.text;
const phone = $('Extrair Mensagem').item.json.phone;
const userId = $('Identificar Usuário').item.json.id;

const valueMatch = text.match(/([\d]+[.,]?[\d]*)/);
if (!valueMatch) {
  return [{ json: { phone, message: '❓ Não entendi o valor. Envie assim:\n\n*gastei 50 almoço*\n*comprei 89,90 mercado*', skip: true } }];
}

const amount = parseFloat(valueMatch[1].replace(',', '.'));

const parts = text.split(valueMatch[0]);
let description = (parts[1] || 'Despesa via WhatsApp').trim();
if (!description || description.length < 2) description = 'Despesa via WhatsApp';
description = description.charAt(0).toUpperCase() + description.slice(1);

const id = crypto.randomUUID ? crypto.randomUUID() : `wpp-${Date.now()}`;

return [{
  json: {
    phone,
    userId,
    skip: false,
    transaction: {
      id,
      user_id: userId,
      description,
      amount,
      type: 'expense',
      date: new Date().toISOString().split('T')[0],
      account_id: null,
      category_id: null
    },
    confirmMessage: `✅ *Despesa registrada!*\n\n💸 *${description}*\nValor: R$ ${amount.toFixed(2)}\nData: ${new Date().toLocaleDateString('pt-BR')}\n\n_Registrado via WhatsApp Fin_`
  }
}];

const profile = $('Buscar Usuários Alertas').item.json;
const accounts = $('Contas (Alertas)').all().map(i => i.json);
const fixedTxs = $('Fixas (Alertas)').all().map(i => i.json);
const budgets = $('Orçamentos (Alertas)').all().map(i => i.json);
const transactions = $('Transações (Alertas)').all().map(i => i.json);

const alerts = [];
const today = new Date();
const currentDay = today.getDate();

// 1. SALDO BAIXO
if (profile.notify_low_balance) {
  const threshold = Number(profile.low_balance_threshold) || 100;
  for (const acc of accounts) {
    const balance = Number(acc.balance);
    if (balance < threshold) {
      alerts.push(`⚠️ *Saldo baixo*: "${acc.name}" com R$ ${balance.toFixed(2)} (limite: R$ ${threshold.toFixed(2)})`);
    }
  }
}

// 2. CONTAS FIXAS A VENCER
if (profile.notify_fixed_due) {
  const daysBefore = Number(profile.fixed_due_days) || 3;
  for (const ft of fixedTxs) {
    const dueDay = Number(ft.day_of_month);
    let daysUntilDue = dueDay - currentDay;
    if (daysUntilDue < 0) continue;
    if (daysUntilDue <= daysBefore) {
      const emoji = ft.type === 'expense' ? '💸' : '💰';
      const when = daysUntilDue === 0 ? 'HOJE' : `em ${daysUntilDue} dia(s)`;
      alerts.push(`${emoji} *${ft.description}* vence ${when} — R$ ${Number(ft.amount).toFixed(2)}`);
    }
  }
}

// 3. ORÇAMENTO ESTOURANDO
if (profile.notify_budget_alert) {
  const alertPct = (Number(profile.budget_alert_percentage) || 80) / 100;
  for (const budget of budgets) {
    const spent = transactions
      .filter(t => t.category_id === budget.category_id)
      .reduce((sum, t) => sum + Number(t.amount), 0);
    const limit = Number(budget.monthly_limit);
    if (limit <= 0) continue;
    const pct = spent / limit;
    if (pct >= alertPct) {
      alerts.push(`🔴 *Orçamento*: Gastou ${(pct * 100).toFixed(0)}% do limite (R$ ${spent.toFixed(2)} de R$ ${limit.toFixed(2)})`);
    }
  }
}

if (alerts.length === 0) return [];

const hour = today.getHours();
const greeting = hour < 12 ? 'Bom dia' : hour < 18 ? 'Boa tarde' : 'Boa noite';
const name = profile.first_name || 'Usuário';

const message = [
  `${greeting}, ${name}! 📊`,
  '', 'Seus alertas financeiros:', '',
  ...alerts,
  '', '---',
  `_WhatsApp Fin • ${today.toLocaleDateString('pt-BR')}_`
].join('\n');

return [{ json: { phone: profile.phone, message, alertCount: alerts.length } }];
